String sql = "SELECT id, email, created_at FROM users WHERE active = true";

try (Connection conn = dataSource.getConnection();
     Statement stmt = conn.createStatement();
     ResultSet rs = stmt.executeQuery(sql)) {

    // Cursor starts BEFORE first row
    while (rs.next()) {  // Move to next row, returns false when done
        long userId = rs.getLong("id");           // By column name
        String email = rs.getString(2);           // By 1-based index
        var createdAt = rs.getTimestamp("created_at");

        System.out.printf("User %d: %s (joined %s)%n", 
                         userId, email, createdAt);
    }
    // rs.next() returned false - no more rows
} catch (SQLException e) {
    throw new RuntimeException("Query failed", e);
}

String sql = "SELECT user_id, age, bio FROM profiles WHERE user_id = ?";

try (Connection conn = dataSource.getConnection();
     PreparedStatement pstmt = conn.prepareStatement(sql)) {

    pstmt.setLong(1, 12345L);

    try (ResultSet rs = pstmt.executeQuery()) {
        if (rs.next()) {
            long userId = rs.getLong("user_id");

            int age = rs.getInt("age");        // Returns 0 if NULL
            Integer ageOrNull = rs.wasNull() ? null : age;  // Check immediately

            String bio = rs.getString("bio");  // Returns null directly if NULL

            System.out.printf("User %d: age=%s, bio=%s%n",
                            userId, ageOrNull, bio != null ? bio : "(none)");
        }
    }
}

record Customer(Long id, String name, String email, LocalDate joinedAt) {}

String sql = "SELECT id, name, email, joined_at FROM customers WHERE active = true";
var customers = new ArrayList<Customer>();

try (Connection conn = dataSource.getConnection();
     Statement stmt = conn.createStatement();
     ResultSet rs = stmt.executeQuery(sql)) {

    while (rs.next()) {
        long id = rs.getLong("id");
        String name = rs.getString("name");
        String email = rs.getString("email");
        var joinedAt = rs.getDate("joined_at").toLocalDate();  // SQL Date to LocalDate

        customers.add(new Customer(id, name, email, joinedAt));  // Build object per row
    }
}

System.out.printf("Loaded %d customers%n", customers.size());

// WRONG: ResultSet not closed if exception occurs
Connection conn = dataSource.getConnection();
Statement stmt = conn.createStatement();
ResultSet rs = stmt.executeQuery("SELECT * FROM orders");
// If exception here, rs/stmt/conn leak
while (rs.next()) { /* process */ }
rs.close(); stmt.close(); conn.close();  // May never execute

// CORRECT: try-with-resources closes automatically
try (Connection conn = dataSource.getConnection();
     Statement stmt = conn.createStatement();
     ResultSet rs = stmt.executeQuery("SELECT * FROM orders")) {

    while (rs.next()) {
        long orderId = rs.getLong("id");
        System.out.println("Processing order " + orderId);
    }
    // rs, stmt, conn closed automatically in reverse order
}

String sql = "SELECT id, name, email FROM users LIMIT 5";

try (Connection conn = dataSource.getConnection();
     Statement stmt = conn.createStatement();
     ResultSet rs = stmt.executeQuery(sql)) {

    ResultSetMetaData meta = rs.getMetaData();  // Get metadata
    int colCount = meta.getColumnCount();

    // Print column headers
    for (int i = 1; i <= colCount; i++) {  // 1-based index
        String colName = meta.getColumnName(i);
        String colType = meta.getColumnTypeName(i);
        System.out.printf("Column %d: %s (%s)%n", i, colName, colType);
    }

    // Print rows dynamically
    while (rs.next()) {
        for (int i = 1; i <= colCount; i++) {
            System.out.print(rs.getString(i) + "\t");  // Generic access
        }
        System.out.println();
    }
}

String sql = "SELECT order_id, item_count, notes FROM orders WHERE order_id = ?";

try (Connection conn = dataSource.getConnection();
     PreparedStatement pstmt = conn.prepareStatement(sql)) {

    pstmt.setLong(1, 42L);

    try (ResultSet rs = pstmt.executeQuery()) {
        if (rs.next()) {
            long orderId = rs.getLong("order_id");

            // Approach 1: wasNull() pattern for primitives
            int itemCount = rs.getInt("item_count");  // Returns 0 if NULL
            Integer count = rs.wasNull() ? null : itemCount;

            // Approach 2: getObject() for nullable primitive
            Integer countAlt = rs.getObject("item_count", Integer.class);  // Returns null if NULL

            // Reference types return null directly
            String notes = rs.getString("notes");  // null if NULL

            System.out.printf("Order %d: count=%s, notes=%s%n", orderId, count, notes);
        }
    }
}
